bool isPerfectSquare(int n) {
  if (n < 0) {
    return false;
  }
  if (n == 0) {
    return true;
  }

  var I = 1;
  while (true) {
    final square = I * i;
    if (square == n) {
      return true;
    } else if (square > n) {
      return false;
    }
    i++;
  }
}

