Function maxProduct(arr) {
  // sort the array in descending order
  arr.sort(function(a, b) {
    return b - a;
  });
  // multiply the two largest numbers
  var maxProduct = arr[0] * arr[1];
  // loop through the array and check for a larger product 
  for (var I = 2; I < arr.length; i++) {
    // multiply the current number with the second-largest number
    var product = arr[i] * arr[1];
    // check if this product is greater than the current max product
    if (product > maxProduct) {
      maxProduct = product;
    }
  }
  return maxProduct;
}

